1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Ledgerly Invoices</title>
7	<style>
8	  * { box-sizing: border-box }
9	  body { margin: 0; font-family: system-ui, sans-serif; background: #f5f6f8; color: #1f2530 }
10	  header { background: #fff; border-bottom: 1px solid #e4e7ec; padding: 16px 32px; display: flex; justify-content: space-between; align-items: center }
11	  .logo { font-weight: 700 }
12	  header a { font-size: 14px; color: #2456c4 }
13	  main { max-width: 680px; margin: 40px auto; padding: 0 24px }
14	  h1 { font-size: 24px; margin: 0 0 8px }
15	  p.sub { color: #525c69; margin: 0 0 24px }
16	  table { width: 100%; border-collapse: collapse; background: #fff; border: 1px solid #e4e7ec; border-radius: 8px }
17	  th, td { text-align: left; padding: 12px 16px; font-size: 14px; border-bottom: 1px solid #edeff3 }
18	  th { color: #5b6571 }
19	  .toolbar { margin: 20px 0 }
20	  .toolbar button { padding: 11px 18px; background: #2456c4; color: #fff; border: 0; border-radius: 7px; font-size: 14px; font-weight: 600; cursor: pointer }
21	  .overlay { position: fixed; inset: 0; background: rgba(20, 24, 32, 0.5); display: none }
22	  .overlay.open { display: block }
23	  .modal { position: fixed; top: 50%; left: 50%; transform: translate(-50%, -50%); width: 380px; background: #fff; border-radius: 10px; padding: 26px; display: none }
24	  .modal.open { display: block }
25	  .modal h2 { font-size: 18px; margin: 0 0 14px }
26	  .modal input { width: 100%; padding: 10px 12px; margin-bottom: 14px; border: 1px solid #c6ccd4; border-radius: 6px; font-size: 14px }
27	  .modal .row { display: flex; gap: 10px; justify-content: flex-end }
28	  .modal .row .ghost { background: #eef0f3; color: #1f2530 }
29	  .modal .row button { padding: 10px 16px; border: 0; border-radius: 6px; font-size: 14px; font-weight: 600; cursor: pointer; background: #2456c4; color: #fff }
30	</style>
31	<script>
32	  window.__activated = []
33	  document.addEventListener('click', function (e) {
34	    var hit = e.target instanceof Element ? e.target.closest('[data-track]') : null
35	    var name = hit ? hit.getAttribute('data-track') : null
36	    if (name) window.__activated.push(name)
37	  })
38	</script>
39	</head>
40	<body>
41	<header>
42	  <span class="logo">Ledgerly</span>
43	  <a href="#help" data-track="help-link">Help center</a>
44	</header>
45	<main>
46	  <h1>Invoices</h1>
47	  <p class="sub">Everything sent this quarter, newest first.</p>
48	  <div class="toolbar">
49	    <button type="button" data-track="open-modal">New invoice</button>
50	  </div>
51	  <table>
52	    <thead>
53	      <tr><th>Number</th><th>Client</th><th>Amount</th><th>Status</th></tr>
54	    </thead>
55	    <tbody>
56	      <tr><td>INV-1042</td><td>Northwind Traders</td><td>$2,400.00</td><td>Paid</td></tr>
57	      <tr><td>INV-1041</td><td>Fabrikam</td><td>$860.00</td><td>Sent</td></tr>
58	      <tr><td>INV-1040</td><td>Contoso</td><td>$1,150.00</td><td>Overdue</td></tr>
59	    </tbody>
60	  </table>
61	  <p id="help" style="font-size: 13px; color: #545e6b">Need a hand? The help center covers numbering, taxes and reminders.</p>
62	</main>
63	<div class="overlay" id="overlay"></div>
64	<div class="modal" id="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title">
65	  <h2 id="modal-title">New invoice</h2>
66	  <input type="text" aria-label="Client name" placeholder="Client name">
67	  <input type="text" aria-label="Amount" placeholder="Amount">
68	  <div class="row">
69	    <button type="button" class="ghost" data-track="cancel-modal">Cancel</button>
70	    <button type="button" data-track="create-invoice">Create</button>
71	  </div>
72	</div>
73	<script>
74	  var overlay = document.getElementById('overlay')
75	  var modal = document.getElementById('modal')
76	  var openBtn = document.querySelector('[data-track="open-modal"]')
77	  var cancelBtn = document.querySelector('[data-track="cancel-modal"]')
78	  var createBtn = document.querySelector('[data-track="create-invoice"]')
79	  var previouslyFocused = null
80	
81	  function getFocusableElements(container) {
82	    return container.querySelectorAll('input, button, [tabindex]')
83	  }
84	
85	  function openModal() {
86	    overlay.classList.add('open')
87	    modal.classList.add('open')
88	    previouslyFocused = document.activeElement
89	    // Move focus to first focusable element in modal (first input)
90	    var focusable = getFocusableElements(modal)
91	    if (focusable.length > 0) {
92	      focusable[0].focus()
93	    }
94	  }
95	
96	  function closeModal() {
97	    overlay.classList.remove('open')
98	    modal.classList.remove('open')
99	    // Return focus to the button that opened the modal
100	    if (previouslyFocused) {
101	      previouslyFocused.focus()
102	    }
103	  }
104	
105	  openBtn.addEventListener('click', openModal)
106	  cancelBtn.addEventListener('click', closeModal)
107	  createBtn.addEventListener('click', closeModal)
108	
109	  // Handle Escape key to close modal
110	  document.addEventListener('keydown', function (e) {
111	    if (e.key === 'Escape' && modal.classList.contains('open')) {
112	      closeModal()
113	    }
114	  })
115	
116	  // Focus trap: keep focus within modal when it's open
117	  modal.addEventListener('keydown', function (e) {
118	    if (e.key !== 'Tab') return
119	
120	    var focusable = getFocusableElements(modal)
121	    if (focusable.length === 0) return
122	
123	    var firstElement = focusable[0]
124	    var lastElement = focusable[focusable.length - 1]
125	    var activeElement = document.activeElement
126	
127	    if (e.shiftKey) {
128	      // Shift+Tab
129	      if (activeElement === firstElement) {
130	        e.preventDefault()
131	        lastElement.focus()
132	      }
133	    } else {
134	      // Tab
135	      if (activeElement === lastElement) {
136	        e.preventDefault()
137	        firstElement.focus()
138	      }
139	    }
140	  })
141	</script>
142	</body>
143	</html>
